import { MakeLogicType, actions, afterMount, beforeUnmount, connect, kea, listeners, path, selectors } from 'kea'

import type { ElementPathsView } from '~/toolbar/shared/element-paths/elementPaths'
import {
    captureElementPathsSaveClicked,
    captureElementPathsViewed,
} from '~/toolbar/shared/element-paths/elementPathsTelemetry'

import type { PageToolbarCommand, PageToolbarState } from '../../messaging/pageToolbarBridge'
import { extensionPageToolbarConnectionLogic } from './extensionPageToolbarConnectionLogic'

const IDLE_VIEW: ElementPathsView = { status: 'idle' }

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface extensionJourneysLogicValues {
    pageToolbarState: PageToolbarState | null // extensionPageToolbarConnectionLogic
    elementPathsView: ElementPathsView
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface extensionJourneysLogicActions {
    receivePatch: (patch: Partial<PageToolbarState>) => {
        patch: Partial<PageToolbarState>
    } // extensionPageToolbarConnectionLogic
    receiveState: (state: PageToolbarState | null) => {
        state: PageToolbarState | null
    } // extensionPageToolbarConnectionLogic
    sendCommand: (message: PageToolbarCommand) => {
        message: PageToolbarCommand
    } // extensionPageToolbarConnectionLogic
    reportSaveClicked: (pathIndex: number) => {
        pathIndex: number
    }
    retryElementPaths: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface extensionJourneysLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        elementPathsView: (pageToolbarState: PageToolbarState | null) => ElementPathsView
    }
}

export type extensionJourneysLogicType = MakeLogicType<
    extensionJourneysLogicValues,
    extensionJourneysLogicActions,
    Record<string, any>,
    extensionJourneysLogicMeta
>

/**
 * The panel side of the journeys section. The page loads paths only while this logic is mounted, because each
 * selection runs a query. The page's copy of posthog-js never sends, so the panel reports what the section shows.
 */
export const extensionJourneysLogic = kea<extensionJourneysLogicType>([
    path(['toolbar', 'extension', 'extensionJourneysLogic']),
    connect(() => ({
        values: [extensionPageToolbarConnectionLogic, ['pageToolbarState']],
        actions: [extensionPageToolbarConnectionLogic, ['sendCommand', 'receiveState', 'receivePatch']],
    })),
    actions({
        retryElementPaths: true,
        reportSaveClicked: (pathIndex: number) => ({ pathIndex }),
    }),
    selectors({
        elementPathsView: [
            (s) => [s.pageToolbarState],
            (pageToolbarState: PageToolbarState | null): ElementPathsView =>
                pageToolbarState?.journeys.view ?? IDLE_VIEW,
        ],
    }),
    listeners(({ actions, values, cache }) => {
        const onPageState = (): void => {
            // A content script that restarts its tools comes back with the paths off.
            if (values.pageToolbarState?.journeys.enabled === false) {
                actions.sendCommand({ tool: 'journeys', command: { type: 'set-enabled', enabled: true } })
            }
            const view = values.elementPathsView
            // A reconnect sends the whole state again, so compare by value to report each answer once.
            const viewKey = JSON.stringify(view)
            if (viewKey !== cache.lastViewKey) {
                cache.lastViewKey = viewKey
                captureElementPathsViewed(view, { source: 'extension' })
            }
        }
        return {
            receiveState: onPageState,
            receivePatch: ({ patch }) => {
                if (patch.journeys) {
                    onPageState()
                }
            },
            retryElementPaths: () => {
                actions.sendCommand({ tool: 'journeys', command: { type: 'retry' } })
            },
            reportSaveClicked: ({ pathIndex }) => {
                captureElementPathsSaveClicked(values.elementPathsView, pathIndex, { source: 'extension' })
            },
        }
    }),
    afterMount(({ actions }) => {
        actions.sendCommand({ tool: 'journeys', command: { type: 'set-enabled', enabled: true } })
    }),
    beforeUnmount(({ actions }) => {
        actions.sendCommand({ tool: 'journeys', command: { type: 'set-enabled', enabled: false } })
    }),
])
